import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';
import { randomBytes } from 'node:crypto';

// Books live in memory and every change is written to a JSON file. Writes go
// through a queue so they never interleave, and each one goes to a temp file
// that is renamed into place, so a crash mid-write can't leave a half-written file.
export async function openStore(file) {
  let books = [];
  try {
    books = JSON.parse(await readFile(file, 'utf8'));
  } catch (err) {
    // A missing file just means no books yet. Anything else (e.g. corrupt
    // JSON) should stop startup rather than risk overwriting the user's data.
    if (err.code !== 'ENOENT') {
      throw new Error(`Could not read ${file}: ${err.message}`);
    }
  }

  let queue = Promise.resolve();

  // Runs fn against the current books; if it returns a new list, that list is
  // saved and then becomes current. Memory only changes after a successful write.
  function update(fn) {
    const run = queue.then(async () => {
      const result = fn(books);
      if (result.books !== books) {
        await mkdir(dirname(file), { recursive: true });
        const tmp = `${file}.tmp`;
        await writeFile(tmp, JSON.stringify(result.books, null, 2) + '\n');
        await rename(tmp, file);
        books = result.books;
      }
      return result.value;
    });
    queue = run.catch(() => {});
    return run;
  }

  return {
    list() {
      return books;
    },

    get(id) {
      return books.find((b) => b.id === id) ?? null;
    },

    add({ title, author, notes }) {
      const book = {
        id: randomBytes(6).toString('base64url'),
        title,
        author,
        notes,
        status: 'reading',
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      return update((current) => ({ books: [...current, book], value: book }));
    },

    // Returns the updated book, or null if there's no book with that id.
    finish(id) {
      return update((current) => {
        const book = current.find((b) => b.id === id);
        if (!book) return { books: current, value: null };
        if (book.status === 'finished') return { books: current, value: book };
        const done = { ...book, status: 'finished', finishedAt: new Date().toISOString() };
        return { books: current.map((b) => (b.id === id ? done : b)), value: done };
      });
    },
  };
}

