export function escape(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function formatDate(iso) {
  return new Date(iso).toLocaleDateString('en-GB', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
  });
}

const styles = `
  body { font: 16px/1.5 system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; color: #222; }
  a { color: #1a5fb4; }
  h1 { margin-bottom: 0.25rem; }
  h2 { margin-top: 2rem; border-bottom: 1px solid #ddd; padding-bottom: 0.25rem; }
  ul.books { list-style: none; padding: 0; }
  ul.books li { display: flex; align-items: center; gap: 0.75rem; padding: 0.5rem 0; border-bottom: 1px solid #eee; }
  ul.books li .info { flex: 1; }
  .muted { color: #666; }
  .empty { color: #666; font-style: italic; }
  .error { background: #fde8e8; color: #8b1a1a; padding: 0.5rem 0.75rem; border-radius: 4px; }
  form.add label { display: block; margin-top: 0.75rem; font-weight: 600; }
  form.add input, form.add textarea { width: 100%; box-sizing: border-box; font: inherit; padding: 0.4rem; }
  form.add textarea { min-height: 6rem; }
  form.add button { margin-top: 1rem; }
  button { font: inherit; padding: 0.3rem 0.8rem; cursor: pointer; }
  .notes { white-space: pre-wrap; background: #f7f7f7; padding: 0.75rem 1rem; border-radius: 4px; }
`;

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escape(title)}</title>
<style>${styles}</style>
</head>
<body>
${body}
</body>
</html>`;
}

function finishButton(book, back) {
  return `<form method="post" action="/books/${escape(book.id)}/finish">
    <input type="hidden" name="back" value="${back}">
    <button type="submit">Mark finished</button>
  </form>`;
}

function byLine(book) {
  return book.author ? `by ${escape(book.author)}` : '';
}

export function homePage(books, { error = null, values = {} } = {}) {
  const reading = books.filter((b) => b.status === 'reading');
  const finished = books
    .filter((b) => b.status === 'finished')
    .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));

  const readingList = reading.length
    ? `<ul class="books">${reading
        .map(
          (b) => `<li>
      <span class="info"><a href="/books/${escape(b.id)}">${escape(b.title)}</a> <span class="muted">${byLine(b)}</span></span>
      ${finishButton(b, 'list')}
    </li>`,
        )
        .join('')}</ul>`
    : `<p class="empty">Nothing on the go right now.</p>`;

  const finishedList = finished.length
    ? `<ul class="books">${finished
        .map(
          (b) => `<li>
      <span class="info"><a href="/books/${escape(b.id)}">${escape(b.title)}</a> <span class="muted">${byLine(b)}</span></span>
      <span class="muted">${formatDate(b.finishedAt)}</span>
    </li>`,
        )
        .join('')}</ul>`
    : `<p class="empty">No finished books yet.</p>`;

  return layout(
    'My books',
    `<h1>My books</h1>

<h2>Currently reading</h2>
${readingList}

<h2>Finished</h2>
${finishedList}

<h2 id="add">Add a book</h2>
${error ? `<p class="error">${escape(error)}</p>` : ''}
<form class="add" method="post" action="/books">
  <label for="title">Title</label>
  <input id="title" name="title" required maxlength="200" value="${escape(values.title)}">
  <label for="author">Author</label>
  <input id="author" name="author" maxlength="200" value="${escape(values.author)}">
  <label for="notes">Notes</label>
  <textarea id="notes" name="notes" maxlength="10000">${escape(values.notes)}</textarea>
  <button type="submit">Add book</button>
</form>`,
  );
}

export function bookPage(book) {
  const status =
    book.status === 'finished'
      ? `Finished ${formatDate(book.finishedAt)}`
      : `Reading since ${formatDate(book.addedAt)}`;

  return layout(
    book.author ? `${book.title} by ${book.author}` : book.title,
    `<p><a href="/">&larr; All books</a></p>
<h1>${escape(book.title)}</h1>
<p class="muted">${byLine(book)}</p>
<p>${status}</p>
${book.status === 'reading' ? finishButton(book, 'book') : ''}

<h2>Notes</h2>
${book.notes ? `<div class="notes">${escape(book.notes)}</div>` : `<p class="empty">No notes.</p>`}`,
  );
}

export function errorPage(status, message) {
  return layout(message, `<h1>${escape(message)}</h1>
<p><a href="/">Back to all books</a></p>`);
}

