import { createServer } from 'node:http';
import { bookPage, errorPage, homePage } from './views.js';

const MAX_BODY_BYTES = 64 * 1024;
const LIMITS = { title: 200, author: 200, notes: 10000 };

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

function sendHtml(res, status, html) {
  res.writeHead(status, {
    'Content-Type': 'text/html; charset=utf-8',
    'Content-Security-Policy': "default-src 'none'; style-src 'unsafe-inline'; form-action 'self'",
    'X-Content-Type-Options': 'nosniff',
  });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

async function readForm(req) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) throw new HttpError(413, 'That was too much text');
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

function validateBook(form) {
  const values = {
    title: (form.get('title') ?? '').trim(),
    author: (form.get('author') ?? '').trim(),
    // Keep the notes' own line breaks, just drop leading/trailing blank space.
    notes: (form.get('notes') ?? '').replace(/\r\n/g, '\n').trim(),
  };
  let error = null;
  if (!values.title) {
    error = 'Please give the book a title.';
  } else {
    for (const [field, max] of Object.entries(LIMITS)) {
      if (values[field].length > max) {
        error = `The ${field} can be at most ${max} characters.`;
        break;
      }
    }
  }
  return { values, error };
}

export function createApp(store) {
  async function handle(req, res) {
    const { pathname } = new URL(req.url, 'http://localhost');
    const method = req.method;

    if (pathname === '/') {
      if (method !== 'GET') throw new HttpError(405, 'Method not allowed');
      return sendHtml(res, 200, homePage(store.list()));
    }

    if (pathname === '/books') {
      if (method !== 'POST') throw new HttpError(405, 'Method not allowed');
      const { values, error } = validateBook(await readForm(req));
      if (error) return sendHtml(res, 400, homePage(store.list(), { error, values }));
      await store.add(values);
      return redirect(res, '/');
    }

    const bookMatch = pathname.match(/^\/books\/([\w-]+)$/);
    if (bookMatch) {
      if (method !== 'GET') throw new HttpError(405, 'Method not allowed');
      const book = store.get(bookMatch[1]);
      if (!book) throw new HttpError(404, 'Book not found');
      return sendHtml(res, 200, bookPage(book));
    }

    const finishMatch = pathname.match(/^\/books\/([\w-]+)\/finish$/);
    if (finishMatch) {
      if (method !== 'POST') throw new HttpError(405, 'Method not allowed');
      const form = await readForm(req);
      const book = await store.finish(finishMatch[1]);
      if (!book) throw new HttpError(404, 'Book not found');
      return redirect(res, form.get('back') === 'book' ? `/books/${book.id}` : '/');
    }

    throw new HttpError(404, 'Page not found');
  }

  return createServer(async (req, res) => {
    try {
      await handle(req, res);
    } catch (err) {
      const status = err instanceof HttpError ? err.status : 500;
      if (status === 500) console.error(err);
      if (!res.headersSent) {
        sendHtml(res, status, errorPage(status === 500 ? 'Something went wrong' : err.message));
      }
    }
  });
}

