import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createApp } from '../src/app.js';
import { openStore } from '../src/store.js';

let dir;
let file;
let server;
let base;

async function start() {
  const store = await openStore(file);
  server = createApp(store);
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  base = `http://127.0.0.1:${server.address().port}`;
  return store;
}

async function stop() {
  await new Promise((resolve) => server.close(resolve));
}

function post(path, fields) {
  return fetch(base + path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(fields),
    redirect: 'manual',
  });
}

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-'));
  file = join(dir, 'books.json');
});

afterEach(async () => {
  await stop();
  await rm(dir, { recursive: true, force: true });
});

describe('home page', () => {
  it('shows empty states when there are no books', async () => {
    await start();
    const html = await (await fetch(base + '/')).text();
    expect(html).toContain('Currently reading');
    expect(html).toContain('Nothing on the go right now.');
    expect(html).toContain('No finished books yet.');
  });

  it('adds a book from the form and lists it as currently reading', async () => {
    const store = await start();
    const res = await post('/books', { title: 'Middlemarch', author: 'George Eliot', notes: 'Slow start' });
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');

    const [book] = store.list();
    expect(book).toMatchObject({ title: 'Middlemarch', author: 'George Eliot', notes: 'Slow start', status: 'reading' });

    const html = await (await fetch(base + '/')).text();
    expect(html).toContain(`<a href="/books/${book.id}">Middlemarch</a>`);
    expect(html).not.toContain('Nothing on the go right now.');
  });

  it('rejects a book without a title and keeps what was typed', async () => {
    const store = await start();
    const res = await post('/books', { title: '   ', author: 'Anon', notes: 'keep me' });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain('Please give the book a title.');
    expect(html).toContain('value="Anon"');
    expect(html).toContain('keep me</textarea>');
    expect(store.list()).toHaveLength(0);
  });

  it('rejects overly long fields', async () => {
    const store = await start();
    const res = await post('/books', { title: 'x'.repeat(201) });
    expect(res.status).toBe(400);
    expect(store.list()).toHaveLength(0);
  });
});

describe('book page', () => {
  it('shows title, author and notes at a shareable URL', async () => {
    const store = await start();
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert', notes: 'Line one\nLine two' });
    const res = await fetch(`${base}/books/${book.id}`);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toContain('<title>Dune by Frank Herbert</title>');
    expect(html).toContain('<h1>Dune</h1>');
    expect(html).toContain('by Frank Herbert');
    expect(html).toContain('Line one\nLine two');
  });

  it('escapes user-entered text', async () => {
    const store = await start();
    const book = await store.add({ title: '<script>alert(1)</script>', author: '"Q"', notes: '<b>hi</b>' });
    const html = await (await fetch(`${base}/books/${book.id}`)).text();
    expect(html).not.toContain('<script>alert(1)</script>');
    expect(html).toContain('&lt;script&gt;alert(1)&lt;/script&gt;');
    expect(html).toContain('&lt;b&gt;hi&lt;/b&gt;');
  });

  it('returns 404 for an unknown book', async () => {
    await start();
    const res = await fetch(`${base}/books/nope`);
    expect(res.status).toBe(404);
    expect(await res.text()).toContain('Book not found');
  });
});

describe('marking finished', () => {
  it('moves a book to finished and redirects back to the list', async () => {
    const store = await start();
    const book = await store.add({ title: 'Emma', author: 'Jane Austen', notes: '' });
    const res = await post(`/books/${book.id}/finish`, { back: 'list' });
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');
    expect(store.get(book.id).status).toBe('finished');
    expect(store.get(book.id).finishedAt).toBeTruthy();

    const html = await (await fetch(base + '/')).text();
    expect(html).toContain('Nothing on the go right now.');
    expect(html).not.toContain('No finished books yet.');
  });

  it('redirects back to the book page when finished from there', async () => {
    const store = await start();
    const book = await store.add({ title: 'Emma', author: '', notes: '' });
    const res = await post(`/books/${book.id}/finish`, { back: 'book' });
    expect(res.headers.get('location')).toBe(`/books/${book.id}`);
    const html = await (await fetch(`${base}/books/${book.id}`)).text();
    expect(html).toContain('Finished');
    expect(html).not.toContain('Mark finished');
  });

  it('returns 404 when finishing an unknown book', async () => {
    await start();
    const res = await post('/books/nope/finish', {});
    expect(res.status).toBe(404);
  });

  it('does not change a book via GET', async () => {
    const store = await start();
    const book = await store.add({ title: 'Emma', author: '', notes: '' });
    const res = await fetch(`${base}/books/${book.id}/finish`);
    expect(res.status).toBe(405);
    expect(store.get(book.id).status).toBe('reading');
  });
});

describe('persistence', () => {
  it('keeps books after a restart', async () => {
    let store = await start();
    const book = await store.add({ title: 'Beloved', author: 'Toni Morrison', notes: 'Wow' });
    await store.finish(book.id);
    await stop();

    store = await start();
    expect(store.get(book.id)).toMatchObject({ title: 'Beloved', status: 'finished', notes: 'Wow' });
    const saved = JSON.parse(await readFile(file, 'utf8'));
    expect(saved).toHaveLength(1);
  });

  it('keeps every book when several are added at once', async () => {
    const store = await start();
    await Promise.all(
      Array.from({ length: 20 }, (_, i) => post('/books', { title: `Book ${i}` })),
    );
    expect(store.list()).toHaveLength(20);
    expect(JSON.parse(await readFile(file, 'utf8'))).toHaveLength(20);
  });

  it('refuses to start on a corrupt data file instead of overwriting it', async () => {
    await writeFile(file, '{not json');
    await expect(openStore(file)).rejects.toThrow(/Could not read/);
    expect(await readFile(file, 'utf8')).toBe('{not json');
    await start().catch(() => {});
    server = { close: (cb) => cb() };
  });
});

